solution.solution.cpp:
using BinaryOp = int (*)(int, int);

int add(int a, int b) { return a + b; }
int subtract(int a, int b) { return a - b; }
int multiply(int a, int b) { return a * b; }

BinaryOp pick(char symbol)
{
    switch (symbol)
    {
    case '+': return add;
    case '-': return subtract;
    case '*': return multiply;
    default:  return nullptr;
    }
}

unitTests:
TEST("returns the right function") { CHECK(pick('+') == add); CHECK(pick('-') == subtract); CHECK(pick('*') == multiply); }
TEST("the result can be called") { const BinaryOp op{ pick('*') }; CHECK(op != nullptr); if (op) CHECK_EQ(op(6, 7), 42); }
TEST("unknown symbols") { CHECK(pick('/') == nullptr); CHECK(pick('x') == nullptr); }

